// Shared by browser, supplier prompts, admin preview and fidelity review.
export const pillowcoreVariants=[
  {id:'fiber',name:'纤维枕（羽丝绒）',group:'柔软填充',hint:'柔软蓬松 · 圆润边角',zh:'纤维填充枕，柔软矩形鼓包，中心饱满、边缘渐薄、底部受压；羽丝绒是纤维款名称，不画羽毛',en:'FIBER-FILLED pillow: soft rectangular loft, full center, tapered rounded edges and gravity-compressed base; imitation-down fiber is NOT feathers'},
  {id:'soy',name:'大豆纤维枕',group:'柔软填充',hint:'柔和蓬松 · 连续壳布',zh:'大豆纤维类填充枕，柔和矩形轮廓与适中蓬松，完整壳布；不生成黄豆颗粒或额外植物装饰',en:'SOY-FIBER blend style: moderately lofted soft rectangular shell; no visible soybeans or botanical decorations'},
  {id:'down',name:'羽绒 / 羽毛枕',group:'柔软填充',hint:'轻盈软塌 · 自然承托',zh:'羽绒或羽毛类填充枕，轻盈柔软、松弛下陷、圆润薄边，完整防绒壳布；不露羽毛，不虚构绒含量或分仓',en:'DOWN/FEATHER-filled style: soft yielding loft and rounded thin edges within an intact shell; no escaping feathers, invented down percentage or internal chambers'},
  {id:'latex',name:'乳胶枕',group:'定型支撑',hint:'一体定型 · 高低波浪轮廓',zh:'乳胶一体定型高低波浪枕，两条不同高度的长边与中间浅凹，保持弹性实芯轮廓，外罩贴合；孔洞仅在用户提供裸芯参考时呈现',en:'LATEX molded contour: unequal-height long ridges and a shallow central cradle; cohesive elastic core, close-fitting cover, not a loose puff; holes only when an explicit bare-core reference confirms them'},
  {id:'memory',name:'记忆棉枕',group:'定型支撑',hint:'慢回弹款 · 连续曲面',zh:'记忆棉一体高低波浪枕，柔和连续曲面、清楚高低边和中间凹槽，受压局部下陷；不画散棉鼓包或乳胶孔洞',en:'MEMORY-FOAM molded contour: continuous curved surface, high/low long edges and central cradle, local compression; no loose fiber puff or invented latex perforations'},
  {id:'gel',name:'凝胶复合枕',group:'定型支撑',hint:'复合定型 · 完整外罩',zh:'凝胶复合定型枕，记忆棉式连续曲面与完整贴合外罩；凝胶层藏于壳内，不自行加蓝色凝胶、液体或透明剖面',en:'GEL-COMPOSITE contour pillow with cohesive foam geometry and intact fitted cover; gel is internal, no invented blue panel, liquid or transparent cutaway'},
  {id:'buckwheat',name:'荞麦枕',group:'颗粒与复合',hint:'低蓬松 · 稳定颗粒承托',zh:'荞麦壳填充枕，偏低矩形、紧实稳固而非羽绒鼓包，真实微小不均匀起伏，完整壳布不露颗粒',en:'BUCKWHEAT-HULL filled pillow: low stable rectangular volume, subtle granular settling under intact cloth, not a fluffy down puff; no exposed hulls'},
  {id:'cassia',name:'决明子枕',group:'颗粒与复合',hint:'颗粒填充款 · 克制起伏',zh:'决明子颗粒类枕，低到中等蓬松、紧实矩形，壳布完整且局部轻微颗粒起伏；不臆造颗粒比例、分区或药用效果',en:'CASSIA-SEED style pillow: low-to-medium firm rectangular volume, slight granular settling beneath intact cloth; no invented seed ratio, partitions or medical claims'},
  {id:'adjustable',name:'可调节复合枕',group:'颗粒与复合',hint:'复合填充 · 高度按参考',zh:'可调节复合填充枕，默认完整适中蓬松矩形；多芯、可拆层和调节开口仅依明确产品参考，不自动加拉链、剖切或爆炸图',en:'ADJUSTABLE COMPOSITE pillow: intact moderately lofted rectangle by default; multiple cores, removable layers and adjustment closures ONLY when explicitly confirmed; no invented zipper, cutaway or exploded view'}
];
export function pillowcoreVariant(v={}){return pillowcoreVariants.some(x=>x.id===v.pillowcoreVariant)?v.pillowcoreVariant:'fiber'}
export function pillowcoreItem(v={}){return pillowcoreVariants.find(x=>x.id===pillowcoreVariant(v))}
export function pillowcoreProductPrompt(v,zh=false){const x=pillowcoreItem(v);return zh?'枕芯商品：仅1只成品枕芯，包含自身壳布与填充/定型内芯，不是空枕套，也不外加装饰枕套。'+x.zh+'。壳布表面质感不改变内芯轮廓，不凭照片推断成分比例、认证或实测高度。':'Exactly ONE finished PILLOW INSERT with its own shell and filled/molded core, not an empty pillowcase and no extra decorative pillowcase. '+x.en+'. Shell texture must not change core geometry. No inferred composition percentage, certification or measured height.'}
export function pillowcorePlacement(v,zh=false){const b=!!(v.imageBBytes||v.imageB);return zh?(b?'枕芯壳布正面A、真实背面B，侧边及窄缝沿所属相邻壳布，不让B围成正面框。':'仅A时枕芯壳布所有正反面和缝边均用A。')+'花型只用于壳布，不用于内芯或填充物；不添加被子、床单、配套枕套或第二只枕芯。':(b?'PILLOW INSERT A/B: shell FRONT uses original A, actual BACK uses original B; narrow seams follow adjacent shell panels, never a B frame around the A front.':'Only A: ALL pillow-insert shell faces and seams use original A.')+' Print belongs ONLY to shell fabric, never to internal foam or filling. No duvet, sheet, companion pillowcases or second pillow insert.'}
const views={front:['正面整体','front-level view of the complete single pillow'],side:['右斜侧整体','right 45-degree three-quarter view'],left:['左侧整体','left three-quarter view'],right:['右侧整体','right side view'],top:['垂直俯视','strict vertical 90-degree overhead view'],low:['低机位轮廓','low camera at pillow height showing its actual loft'],wide:['场景主图','contextual wide view, pillow stays the clearly readable principal product'],reverse:['背面展示','turn the entire pillow back-up on its support; do not fold the pillow like a duvet'],foot:['短边轮廓','medium-close view of the actual short end and connected upper shell'],detail:['壳布质感','contextual close-up of continuous shell textile'],pillowclose:['缝边特写','contextual close-up of the actual narrow shell seam'],drape:['侧边厚度','side-level close view of actual pillow thickness, not a hanging skirt']};
export function pillowcoreDirection(v,angle){const [name,view]=views[angle]||views.side;return {name,zh:'拍摄'+name+'，仅1只所选枕芯自然承托，定型枕不折叠。保留真实轮廓、壳布及缝边，细节不臆造内部结构。',prompt:'PILLOW INSERT CAMERA: '+view+'. Exactly one selected pillow resting naturally on a neutral support. Apply viewpoint to the pillow itself, not an entire bedding set. Never fold a molded pillow. Preserve core outline, physical contact and intact shell; no invented opening or internal cutaway. Full views keep complete outline with clean margins; close views retain connected shell and principal seam.'}}
export function pillowcoreGuard(v,zh=false){return v.product==='pillowcore'?pillowcoreProductPrompt(v,zh)+' '+pillowcorePlacement(v,zh):''}
